<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">libs-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_OF_EMBED</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> += dts/</span></span>
